-- Seed: the 69 wilayas and one delivery_rates row per wilaya (all switched off).
-- Data only, idempotent (ON CONFLICT DO NOTHING), no deletes or updates.
-- id = official code for the seeded rows so the internal id is stable and readable.
ON CONFLICT DO NOTHING;--> statement-breakpoint
SELECT setval(pg_get_serial_sequence('wilayas', 'id'), GREATEST((SELECT max("id") FROM "wilayas"), 1));--> statement-breakpoint
